INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist der BSI-Grundschutz eine gesetzliche Vorschrift?', 2, '[{"text": "Nein", "correct": true, "because": "Freiwilliger Standard"}, {"text": "Ja", "correct": false, "because": "Keine gesetzliche Pflicht"}]'),
